BASE = 'https://physionet.org/files/bidmc/1.0.0/'
OUT = pathlib.Path(__file__).resolve().parent / 'N2_inputs_v1.0.0'

def sha(b): return hashlib.sha256(b).hexdigest()
def get(url):
    req=urllib.request.Request(url,headers={'User-Agent':'N2-research-input-check/1.0'})
    with urllib.request.urlopen(req, timeout=30) as r: return r.read()

def official_check(lines, name, want):
    matches=[line for line in lines.splitlines() if re.search(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'(?![A-Za-z0-9_.])',line)]
    # Check filename lines strictly: expected SHA appears as a 64-char token.
    if len(matches)!=1 or not re.search(r'(?<![0-9a-fA-F])'+want+r'(?![0-9a-fA-F])',matches[0],re.I):
        raise ValueError('official SHA256SUMS did not verify '+name)

def main():
    assert len(EXPECTED)==106
    OUT.mkdir(parents=True,exist_ok=True)
    checksums=get(BASE+'SHA256SUMS.txt').decode('utf-8-sig')
    report={'dataset':'BIDMC v1.0.0','official_checksum_sha256':sha(checksums.encode('utf-8')),'files':[], 'failures':[]}
    for idx,(name,meta) in enumerate(sorted(EXPECTED.items()),1):
        try:
            expected=meta['sha256'].lower()
            if expected!=meta['official_sha256'].lower(): raise ValueError('manifest hash disagreement')
            official_check(checksums,name,expected)
            target=OUT/name
            if target.exists():
                payload=target.read_bytes()
                mode='cached'
            else:
                payload=get(meta['url'])
                mode='downloaded'
            if len(payload)!=meta['bytes'] or sha(payload)!=expected:
                raise ValueError('size or SHA256 mismatch; local file NOT overwritten')
            if mode=='downloaded': target.write_bytes(payload)
            report['files'].append({'file':name,'sha256':expected,'bytes':len(payload),'mode':mode,'status':'PASS'})
            print(f'{idx:03}/106 PASS {name} ({mode})',flush=True)
        except Exception as e:
            report['failures'].append({'file':name,'error':f'{type(e).__name__}: {e}'})
            print(f'{idx:03}/106 FAIL {name}: {e}',file=sys.stderr,flush=True)
            # Stop on error rather than working around corrupted or changed inputs.
            break
    ids=sorted({int(x['file'][6:8]) for x in report['files']})
    report['record_count']=len(ids)
    report['passed_files']=len(report['files'])
    report['status']='PASS' if len(report['files'])==106 and ids==list(range(1,54)) and not report['failures'] else 'INCOMPLETE'
    (OUT/'N2_Session1_Verification.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print('\nSESSION 1:',report['status'],'files=',report['passed_files'],'records=',len(ids))
    print('Output:',OUT/'N2_Session1_Verification.json')
    return 0 if report['status']=='PASS' else 1

if __name__=='__main__': sys.exit(main())
